<?php
$staff = in_array($account['role'], ['librarian', 'admin'], true);
$admin = $account['role'] === 'admin';
$e = [Library\Web::class, 'escape'];
$form = $form ?? [];
$formError = $formError ?? '';
$roleName = ['reader' => 'Lector', 'librarian' => 'Bibliotecario', 'admin' => 'Administrador'];
$metricName = ['books' => 'Libros', 'available_books' => 'Libros disponibles', 'requests' => 'Solicitudes', 'loans' => 'Préstamos', 'outstanding_loans' => 'Préstamos activos'];
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e(match($page) {'books'=>'Catálogo','users'=>'Usuarios','requests'=>'Solicitudes','loans'=>'Préstamos','accounts'=>'Cuentas',default=>'Resumen'}) ?> | Biblioteca</title><link rel="stylesheet" href="assets/app.css"></head><body><a class="skip" href="#content">Saltar al contenido</a><header class="mobile-header"><button class="nav-toggle" aria-expanded="false" aria-controls="main-nav">Menú</button><strong>Biblioteca</strong></header><aside id="main-nav" class="sidebar"><p class="brand">Biblioteca <span>Académica</span></p><p class="identity"><?= $e($account['username']) ?><br><small><?= $e($roleName[$account['role']] ?? 'Cuenta') ?></small></p><nav aria-label="Navegación principal"><a href="index.php?page=dashboard"<?= $page === 'dashboard' ? ' aria-current="page"' : '' ?>>Resumen</a><a href="index.php?page=books"<?= $page === 'books' ? ' aria-current="page"' : '' ?>>Catálogo</a><a href="index.php?page=requests"<?= $page === 'requests' ? ' aria-current="page"' : '' ?>>Solicitudes</a><a href="index.php?page=loans"<?= $page === 'loans' ? ' aria-current="page"' : '' ?>>Préstamos</a><?php if ($staff): ?><a href="index.php?page=users"<?= $page === 'users' ? ' aria-current="page"' : '' ?>>Usuarios</a><?php endif; ?><?php if ($admin): ?><a href="index.php?page=accounts"<?= $page === 'accounts' ? ' aria-current="page"' : '' ?>>Cuentas</a><?php endif; ?></nav><form method="post" action="index.php"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><button class="link-button" type="submit">Cerrar sesión</button></form></aside><main id="content" class="content"><header class="page-head"><div><p class="eyebrow">Gestión de biblioteca</p><h1><?= $e(match($page) {'books'=>'Catálogo','users'=>'Usuarios de biblioteca','requests'=>'Solicitudes','loans'=>'Préstamos y devoluciones','accounts'=>'Cuentas de acceso',default=>'Resumen'}) ?></h1></div></header><?php if ($notice !== ''): ?><p class="notice" role="status"><?= $e($notice) ?></p><?php endif; ?>
<?php if ($formError !== ''): ?><section class="error-summary" role="alert" tabindex="-1"><h2>Revise el formulario</h2><p><?= $e($formError) ?></p><a href="#form-principal">Ir al campo a corregir</a></section><?php endif; ?>
<?php if ($page === 'dashboard'): ?><section class="metrics" aria-label="Indicadores actuales"><?php foreach ($dashboard['metrics'] as $name=>$value): if (!$staff && in_array($name, ['books','available_books'], true)) continue; ?><article><p><?= $e($metricName[$name] ?? $name) ?></p><strong><?= (int)$value ?></strong></article><?php endforeach; ?></section><section class="info"><h2><?= $staff ? 'Operación actual' : 'Mi actividad' ?></h2><p><?= $staff ? 'Los indicadores reflejan filas actuales del sistema. Confirme solicitudes y registre devoluciones desde las secciones operativas.' : 'Sus indicadores incluyen únicamente sus propias solicitudes y préstamos.' ?></p></section>
<?php elseif ($page === 'books'): ?><section class="toolbar"><form method="get"><input type="hidden" name="page" value="books"><label class="sr-only" for="search">Buscar libros</label><input id="search" type="search" name="q" value="<?= $e($search) ?>" placeholder="Título o autor"><button type="submit">Buscar</button></form></section><?php if ($staff): ?><details class="panel"><summary>Registrar libro</summary><form id="form-principal" class="form-grid" method="post"><input type="hidden" name="action" value="create_book"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><label>Título<input name="title" value="<?= $e($form['title'] ?? '') ?>" required maxlength="150"></label><label>Autor<input name="author" value="<?= $e($form['author'] ?? '') ?>" required maxlength="100"></label><button class="button">Guardar libro</button></form></details><?php endif; ?><table><caption>Resultados del catálogo</caption><thead><tr><th>Título</th><th>Autor</th><th>Estado</th><?php if ($staff): ?><th>Edición</th><?php else: ?><th>Solicitud</th><?php endif; ?></tr></thead><tbody><?php foreach ($books as $book): ?><tr><td><?= $e($book['title']) ?></td><td><?= $e($book['author']) ?></td><td><?= $book['available'] ? 'Disponible' : 'No disponible' ?></td><?php if ($staff): ?><td><details><summary>Editar</summary><form method="post" class="compact"><input type="hidden" name="action" value="edit_book"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><input type="hidden" name="book_id" value="<?= $book['id'] ?>"><label>Título<input name="title" value="<?= $e($book['title']) ?>" required maxlength="150"></label><label>Autor<input name="author" value="<?= $e($book['author']) ?>" required maxlength="100"></label><button>Actualizar</button></form></details></td><?php else: ?><td><form method="post"><input type="hidden" name="action" value="request"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><input type="hidden" name="book_id" value="<?= $book['id'] ?>"><button<?= $book['available'] ? '' : ' disabled' ?>><?= $book['available'] ? 'Solicitar' : 'No disponible' ?></button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table><?php if ($books === []): ?><p class="empty">No hay libros que coincidan con la búsqueda.</p><?php endif; ?>
<?php elseif ($page === 'users'): ?><section class="toolbar"><form method="get"><input type="hidden" name="page" value="users"><label class="sr-only" for="user-search">Buscar usuarios</label><input id="user-search" type="search" name="q" value="<?= $e($search) ?>" placeholder="Nombre o correo"><button type="submit">Buscar</button></form></section><details class="panel"><summary>Registrar usuario de biblioteca</summary><form class="form-grid" method="post"><input type="hidden" name="action" value="create_user"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><label>Nombre<input name="name" required maxlength="100"></label><label>Correo<input type="email" name="email" required maxlength="100"></label><button class="button">Guardar usuario</button></form></details><table><caption>Personas registradas</caption><thead><tr><th>Nombre</th><th>Correo</th><th>Edición</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= $e($user['name']) ?></td><td><?= $e($user['email']) ?></td><td><details><summary>Editar</summary><form class="compact" method="post"><input type="hidden" name="action" value="edit_user"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><input type="hidden" name="user_id" value="<?= $user['id'] ?>"><label>Nombre<input name="name" value="<?= $e($user['name']) ?>" required></label><label>Correo<input type="email" name="email" value="<?= $e($user['email']) ?>" required></label><button>Actualizar</button></form></details></td></tr><?php endforeach; ?></tbody></table>
<?php elseif ($page === 'requests'): ?><table><caption><?= $staff ? 'Solicitudes pendientes y confirmadas' : 'Mis solicitudes' ?></caption><thead><tr><th>Libro</th><?php if ($staff): ?><th>Persona</th><?php endif; ?><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td><?= $e($request['book_title'] ?? 'Libro histórico no disponible') ?></td><?php if ($staff): ?><td><?= $e($request['user_name'] ?? 'Usuario histórico no disponible') ?></td><?php endif; ?><td><?= $e($request['status'] === 'pending' ? 'Pendiente' : 'Confirmada') ?></td><td><?php if ($staff && $request['status'] === 'pending'): ?><form method="post"><input type="hidden" name="action" value="confirm"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><input type="hidden" name="request_id" value="<?= $request['id'] ?>"><button data-confirm="¿Confirmar préstamo?">Confirmar</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$staff): ?><p><a class="button" href="index.php?page=books">Solicitar desde el catálogo</a></p><?php endif; ?>
<?php elseif ($page === 'loans'): ?><table><caption><?= $staff ? 'Historial de préstamos' : 'Mi historial de préstamos' ?></caption><thead><tr><th>Libro</th><th>Fecha</th><th>Estado</th><?php if ($staff): ?><th>Acción</th><?php endif; ?></tr></thead><tbody><?php foreach ($loans as $loan): ?><tr><td><?= $e($loan['book_title'] ?? 'Libro histórico no disponible') ?></td><td><?= $e($loan['issued_on']) ?></td><td><?= $loan['returned'] ? 'Devuelto' : 'Activo' ?></td><?php if ($staff): ?><td><?php if (!$loan['returned']): ?><form method="post"><input type="hidden" name="action" value="return"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><input type="hidden" name="loan_id" value="<?= $loan['id'] ?>"><button data-confirm="¿Registrar devolución?">Registrar devolución</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table>
<?php else: ?><details class="panel"><summary>Aprovisionar cuenta</summary><form class="form-grid" method="post"><input type="hidden" name="action" value="create_account"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><label>Usuario de biblioteca<select name="user_id" required><?php foreach ($users as $user): ?><option value="<?= $user['id'] ?>"><?= $e($user['name']) ?></option><?php endforeach; ?></select></label><label>Nombre de acceso<input name="username" required maxlength="100"></label><label>Contraseña<input type="password" name="password" required minlength="12" maxlength="72"></label><label>Rol<select name="role"><option value="reader">Lector</option><option value="librarian">Bibliotecario</option><option value="admin">Administrador</option></select></label><button class="button">Crear cuenta</button></form></details><table><caption>Cuentas de acceso</caption><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach ($accounts as $item): ?><tr><td><?= $e($item['username']) ?></td><td><?= $e($item['role']) ?></td><td><?= $item['active'] ? 'Activa' : 'Inactiva' ?></td><td><form method="post"><input type="hidden" name="action" value="<?= $item['active'] ? 'deactivate' : 'activate' ?>"><input type="hidden" name="csrf" value="<?= $web->csrf() ?>"><input type="hidden" name="account_id" value="<?= $item['id'] ?>"><button><?= $item['active'] ? 'Desactivar' : 'Activar' ?></button></form></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></main><script src="assets/app.js" defer></script></body></html>
